Python - DualKeyRotatingProvider
from redwood_sdk.auth import DualKeyRotatingProvider
provider = DualKeyRotatingProvider(primary_key=env.get('REDWOOD_KEY_A'), secondary_key=env.get('REDWOOD_KEY_B'), accept_window_days=3)
client = RedwoodClient(auth_provider=provider)
# provider exposes .rotate(now_secondary=True) for manual trigger and events for UI
TypeScript - SsoEphemeralProvider (browser BFF)
import { SsoEphemeralProvider } from '@redwood/sdk-js/auth'
const provider = new SsoEphemeralProvider({mintEndpoint: '/api/mint-ephemeral', refreshMarginSec: 30})
const client = new RedwoodClient({authProvider: provider})
// provider handles popup/redirects via BFF and stores token in browser session storage (documented trade-offs)
Go - Streaming client with reauth hook
provider := auth.NewStaticProvider(os.Getenv('REDWOOD_KEY'))
streamClient := client.NewStreamClient(client.WithAuthProvider(provider), client.WithReauthHandler(func(ctx context.Context) (string, error) {
  // called when server requests refresh; provider.Refresh() may perform token exchange
  return provider.Refresh(ctx)
}))
// Reauth handler must be fast and support context cancellation
